class Controller:
 def __init__(self,s):
  self.s=s; self.m=s.model; self.d=s.data
  self.jd=np.array([self.m.joint('robot0_joint'+str(i)).dofadr[0] for i in range(1,8)])
  self.jq=np.array([self.m.joint('robot0_joint'+str(i)).qposadr[0] for i in range(1,8)])
  self.limits=np.array([self.m.joint('robot0_joint'+str(i)).range for i in range(1,8)])
  self.site=self.m.site('gripper0_right_grip_site').id
  self.scratch=mujoco.MjData(self.m)
  self.a=s.hold_targets(); self.a[7]=-1
 def pose(self): return self.d.site_xpos[self.site].copy(),self.d.site_xmat[self.site].reshape(3,3).copy()
 def obj(self,n): return self.d.xpos[self.m.body(n+'_main').id].copy()
 def ik(self,p,R,q=None):
  d=self.scratch; d.qpos[:]=self.d.qpos
  q=self.d.qpos[self.jq].copy() if q is None else q.copy()
  def fun(q):
   d.qpos[self.jq]=q; mujoco.mj_forward(self.m,d)
   er=Rotation.from_matrix(R@d.site_xmat[self.site].reshape(3,3).T).as_rotvec()
   return np.r_[d.site_xpos[self.site]-p,er*.4]
  r=least_squares(fun,np.clip(q,self.limits[:,0]+1e-5,self.limits[:,1]-1e-5),bounds=(self.limits[:,0]+1e-6,self.limits[:,1]-1e-6),max_nfev=100,xtol=1e-8,ftol=1e-8,gtol=1e-8)
  return r.x,np.linalg.norm(fun(r.x))
 def hold(self,n=10,grip=None):
