 def move(self,p,R=None,n=50,grip=None):
  p0,R0=self.pose(); R=R0 if R is None else np.array(R); p=np.array(p)
  rot=Rotation.from_matrix(R@R0.T).as_rotvec()
  q=self.d.qpos[self.jq].copy(); errors=[]
  if grip is not None:self.a[7]=grip
  for i in range(1,n+1):
   t=i/n; t=t*t*(3-2*t)
   Rt=Rotation.from_rotvec(t*rot).as_matrix()@R0
   q,err=self.ik(p0+(p-p0)*t,Rt,q)
   self.a[:7]=q; self.s.step(self.a); errors.append(err)
  print('move',len(self.s.actions),'target',np.round(p,3),'actual',np.round(self.pose()[0],3),'ikerr',round(max(errors),4),flush=True)
 def pic(self,name='view'):
  Image.fromarray(self.s.render_grid()).save('/app/output/'+name+'.png')
 def status(self):
  print('eef',self.pose()[0],'objects',[(n,self.obj(n)) for n in ['obj1','obj2','mug']], 'check',self.s.check(),flush=True)
